+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+import java.util.regex.Pattern;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<Message> grid = new Grid<>();
+    private final MessageStore store;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+        setPadding(true);
+        setSpacing(true);
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout();
+        form.setAutoResponsive(true);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setMaxWidth("42em");
+        message.setMaxLength(501);
+        form.add(name, email, phone, message);
+        send.addClickListener(e -> submit());
+        send.addClickShortcut(Key.ENTER);
+        name.addKeyPressListener(Key.ENTER, e -> submit());
+        email.addKeyPressListener(Key.ENTER, e -> submit());
+        phone.addKeyPressListener(Key.ENTER, e -> submit());
+        message.addKeyPressListener(Key.ENTER, e -> submit());
+        HorizontalLayout actions = new HorizontalLayout(send);
+        form.add(actions);
+        add(form);
+
+        Runnable edited = () -> send.setEnabled(true);
+        name.addValueChangeListener(e -> edited.run());
+        email.addValueChangeListener(e -> edited.run());
+        phone.addValueChangeListener(e -> edited.run());
+        message.addValueChangeListener(e -> edited.run());
+
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::message).setHeader("Message");
+        grid.setItems(store.all());
+        grid.setWidthFull();
+        add(grid);
+    }
+
+    private void submit() {
+        String n = name.getValue() == null ? "" : name.getValue().trim();
+        String em = email.getValue() == null ? "" : email.getValue().trim();
+        String ph = phone.getValue() == null ? "" : phone.getValue().trim();
+        String msg = message.getValue() == null ? "" : message.getValue();
+        boolean valid = true;
+
+        name.setErrorMessage("Name is required");
+        name.setInvalid(n.isEmpty());
+        valid &= !n.isEmpty();
+
+        boolean badEmail = !em.isEmpty() && !EMAIL.matcher(em).matches();
+        boolean noContact = em.isEmpty() && ph.isEmpty();
+        email.setErrorMessage(badEmail ? "Enter a valid e-mail address" : "Give an e-mail address or a phone number");
+        email.setInvalid(badEmail || noContact);
+        valid &= !badEmail && !noContact;
+
+        boolean blankMessage = msg.trim().isEmpty();
+        boolean tooLong = msg.length() > 500;
+        message.setErrorMessage(blankMessage ? "Message is required" : "Message must be at most 500 characters");
+        message.setInvalid(blankMessage || tooLong);
+        valid &= !blankMessage && !tooLong;
+
+        if (!valid) return;
+        Message sent = new Message(n, em, ph, msg);
+        store.add(sent);
+        grid.setItems(store.all());
+        Notification.show("Message sent");
+        name.clear(); email.clear(); phone.clear(); message.clear();
+        send.setEnabled(false);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (isFormEmpty()) return;
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        Button keep = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> { dialog.close(); navigation.proceed(); });
+        dialog.add(new VerticalLayout(new com.vaadin.flow.component.html.Paragraph("Discard the message you are writing?"), new HorizontalLayout(keep, discard)));
+        dialog.open();
+    }
+
+    private boolean isFormEmpty() {
+        return empty(name.getValue()) && empty(email.getValue()) && empty(phone.getValue()) && empty(message.getValue());
+    }
+    private boolean empty(String value) { return value == null || value.isEmpty(); }
+}
