+package com.example;
+
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+import org.springframework.stereotype.Service;
+
+@Service
+public class MessageStore {
+    public record Message(String name, String email, String phone, String message) { }
+    private final CopyOnWriteArrayList<Message> messages = new CopyOnWriteArrayList<>();
+
+    public void add(Message message) { messages.add(0, message); }
+    public List<Message> all() { return List.copyOf(messages); }
+}
